// Friend-code format shared by the browser and the Convex backend. Keep this
// module free of browser or Convex dependencies so both sides can import it.

/** Crockford-like alphabet without 0, 1, I, and O; exactly 32 symbols. */
export const FRIEND_CODE_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ";
/** Length of codes generated by this client (100 bits of entropy). */
export const FRIEND_CODE_GENERATED_LENGTH = 20;
export const FRIEND_CODE_MIN_LENGTH = 20;
export const FRIEND_CODE_MAX_LENGTH = 32;
/** Raw input longer than this is rejected before normalization. */
export const FRIEND_CODE_MAX_INPUT_LENGTH = 64;
/** Server-enforced cap on friend codes checked per discovery request. */
export const MAX_FOLLOWED_FRIENDS = 50;

const FRIEND_CODE_PATTERN = new RegExp(
  `^[2-9A-HJ-NP-Z]{${FRIEND_CODE_MIN_LENGTH},${FRIEND_CODE_MAX_LENGTH}}$`
);

/** True when `value` is already a canonical (normalized) friend code. */
export function isCanonicalFriendCode(value: string): boolean {
  return FRIEND_CODE_PATTERN.test(value);
}

/**
 * Strictly parses a presented friend code: trims, uppercases, and removes
 * whitespace and hyphen separators. Returns null for anything that is not a
 * valid code, including codes containing ambiguous characters.
 */
export function parseFriendCode(value: string): string | null {
  if (value.length > FRIEND_CODE_MAX_INPUT_LENGTH) return null;
  const normalized = value.trim().toUpperCase().replace(/[\s-]+/g, "");
  return isCanonicalFriendCode(normalized) ? normalized : null;
}
